# Get all public functions in internal/ and count their references more carefully
cat > /tmp/count_all.py << 'EOF'
#!/usr/bin/env python3
import os
import re
import subprocess
from collections import defaultdict

# Find all public functions in internal/
funcs = set()
for root, dirs, files in os.walk("/bench/repo/internal"):
    for file in files:
        if file.endswith(".go") and not file.endswith("_test.go"):
            path = os.path.join(root, file)
            try:
                with open(path, 'r') as f:
                    content = f.read()
                    # Find public functions and methods
                    for match in re.finditer(r'^func (?:\([^)]+\) )?([A-Z][A-Za-z0-9]*)\s*\(', content, re.MULTILINE):
                        funcs.add(match.group(1))
            except:
                pass

# Count references to each
ref_counts = {}
for func in sorted(funcs):
    try:
        result = subprocess.run(
            ['grep', '-r', f'\\b{func}\\s*(', '/bench/repo', '--include=*.go'],
            capture_output=True, text=True
        )
        count = len([l for l in result.stdout.split('\n') if l])
        if count > 0:
            ref_counts[func] = count
    except:
        pass

# Sort and show top 20
for func, count in sorted(ref_counts.items(), key=lambda x: -x[1])[:20]:
    print(f"{count:4d} {func}")
EOF
